// Generated by the Salvo compiler: the array subscript.

/// [col-index-trap] [rs-index-trap] A subscript out of range is Salvo's
/// trap, not the host's: `xs[i]` on an array (a `Vec`) indexes by
/// `SalvoIx(i, at)`, which checks the position and panics with
/// `salvo: index out of range at <module>:<line>:<col>`, the text Kotlin's
/// `salvoIx` throws [assert-trap]. A negative index is converted to a huge
/// position first, so it is out of range too.
///
/// `Vec`'s own `Index` impl is generic over `SliceIndex`, which `SalvoIx`
/// does not implement, so coherence lets this one stand beside it; a
/// `&Vec` and a `&mut Vec` reach it by auto-deref.
#[derive(Clone, Copy, Debug)]
pub struct SalvoIx(pub usize, pub &'static str);

/// Two subscripts are one position when their indices are (a split borrow
/// compares them), wherever they were written.
impl PartialEq for SalvoIx {
    fn eq(&self, other: &Self) -> bool {
        self.0 == other.0
    }
}

impl From<SalvoIx> for usize {
    fn from(i: SalvoIx) -> usize {
        i.0
    }
}

impl<T> std::ops::Index<SalvoIx> for Vec<T> {
    type Output = T;
    fn index(&self, i: SalvoIx) -> &T {
        match self.get(i.0) {
            Some(x) => x,
            None => panic!("salvo: index out of range at {}", i.1),
        }
    }
}

impl<T> std::ops::IndexMut<SalvoIx> for Vec<T> {
    fn index_mut(&mut self, i: SalvoIx) -> &mut T {
        let at = i.1;
        match self.get_mut(i.0) {
            Some(x) => x,
            None => panic!("salvo: index out of range at {at}"),
        }
    }
}
